    fun explanation(code: String): DtcExplanation = catalog[code.uppercase()]
        ?: DtcExplanation(
            "شرح اختصاصی این کد در فهرست عمومی برنامه موجود نیست؛ ممکن است کد مخصوص سازنده خودرو باشد.",
            "بدون اطلاعات سازنده، مدل، سال ساخت و نوع ECU نمی‌توان علت را با اطمینان تعیین کرد.",
            "کد با دستگاه تخصصی و اطلاعات تعمیراتی همان خودرو بررسی شود. از تعویض قطعه صرفاً بر اساس این کد خودداری کنید.",
            "نیازمند بررسی"
        )

    fun description(code: String): String = explanation(code).description

    fun category(code: String): String = when (code.firstOrNull()?.uppercaseChar()) {
        'P' -> "موتور و قوای محرکه"
        'B' -> "بدنه و تجهیزات رفاهی"
        'C' -> "شاسی و سامانه‌های حرکتی"
        'U' -> "شبکه و ارتباطات الکترونیکی"
        else -> "گروه نامشخص"
    }

    fun persianCode(code: String): String {
        val prefix = when (code.firstOrNull()?.uppercaseChar()) {
            'P' -> "پی"
            'B' -> "بی"
            'C' -> "سی"
            'U' -> "یو"
            else -> return code
        }
        val persianDigits = code.drop(1).map { ch ->
            if (ch in '0'..'9') ('۰'.code + (ch - '0')).toChar() else ch
        }.joinToString("")
        return "$prefix‌$persianDigits"
    }
}
